diff --git a/.claudinite/local/packs/canon-curation/pack-version-bumped.mjs b/.claudinite/local/packs/canon-curation/pack-version-bumped.mjs
new file mode 100644
index 00000000..85c200d4
--- /dev/null
+++ b/.claudinite/local/packs/canon-curation/pack-version-bumped.mjs
@@ -0,0 +1,83 @@
+import { finding } from '../../../../engine/checks/helpers/findings.mjs';
+
+// A PACK'S CONTENT IS DELIVERED ON ITS VERSION NUMBER, and on nothing else. The
+// engine tree vendors wholesale on every converge; a pack's directory ships only
+// where `planPackUpdates` sees `installed.packVersions[id] < pack.version`
+// (updates/pack-update.mjs). So a canon commit that edits `packs/<id>/` without
+// touching that number lands here, goes green here, and reaches no member — the
+// fleet keeps the old bytes while canon believes the change shipped.
+//
+// #939 is what that costs. A check vocabulary rename updated the engine and the
+// canon's own packs in one commit: the engine, delivered unconditionally, reached
+// every member and rejected the old spelling; the pack carrying the new spelling
+// stayed at `version: 1` and reached nobody. The mixed tree failed each member's
+// self-test, the update PR parked, and the fix could not arrive by the route that
+// delivers fixes. Seven repos sat frozen for five days.
+//
+// So the invariant this rule holds is one line: A CHANGE UNDER `packs/<id>/` IS A
+// CHANGE TO THAT PACK'S VERSION. Every byte counts, because every byte ships in
+// the same directory copy — prose, a skill, a check module, a migration record.
+// It is the pack-side twin of `engine-release-record` (the claudinite local pack),
+// which holds the same line for `ENGINE_VERSION`.
+//
+// WORK SCOPE: the question is what THIS change did. The tree always contains a
+// version number; only the diff says whether it moved with the content beside it.
+const LOCAL_PACKS = '.claudinite/local/packs';
+
+// The pack ids a changed-file list touches, in first-seen order. Anchored at
+// `packs/<id>/` so the canon's own local packs (which vendor nowhere, carry no
+// version and reach no member) and the tree's own files (`packs/README.md`,
+// `packs/directory.GENERATED.md`) are outside it by construction.
+export function packsTouched(changed) {
+  const ids = [];
+  for (const file of changed ?? []) {
+    if (file.startsWith(`${LOCAL_PACKS}/`)) continue;
+    const m = /^packs\/([^/]+)\//.exec(file);
+    if (m && !ids.includes(m[1])) ids.push(m[1]);
+  }
+  return ids;
+}
+
+// The `version:` a pack manifest declares, or null when it declares none (a
+// manifest that is absent on one side of the diff, or one the schema check owns).
+// The preceding-character class is what keeps `minEngineVersion:` out of it.
+export function declaredPackVersion(text) {
+  const m = /(?:^|[\s{,])version:\s*(\d+)/m.exec(text ?? '');
+  return m ? Number(m[1]) : null;
+}
+
+const rule = {
+  id: 'pack-version-bumped',
+  severity: 'blocking',
+  scope: 'work',
+  description: 'A change under packs/<id>/ bumps that pack\'s version',
+  doc: 'docs/versioned-updates/DESIGN.md',
+  why: 'a member receives a pack directory only when the canon\'s version exceeds the one it has installed, so content edited without a bump reaches nobody while canon CI reports it shipped (#939 froze seven repos for five days that way)',
+
+  run(work) {
+    const findings = [];
+    for (const id of packsTouched(work.changedFiles)) {
+      const manifest = `packs/${id}/pack.mjs`;
+      const head = declaredPackVersion(work.read(manifest));
+      if (head === null) continue;                     // the pack was deleted, or declares no version — other rules own that
+      const base = declaredPackVersion(work.readBase(manifest));
+      if (base === null) continue;                     // a pack this change introduces: its first version ships to everyone
+      if (head > base) continue;
+
+      findings.push(finding(rule, {
+        file: manifest,
+        what: head === base
+          ? `this change edits packs/${id}/ but leaves its version at ${head}`
+          : `packs/${id}/ moves its version backwards, ${base} → ${head}`,
+        fix: head === base
+          ? `raise \`version\` in ${manifest} to ${base + 1} — the number is the whole delivery signal, so an edit that `
+            + 'does not move it stays in the canon forever'
+          : 'pack versions only ever increase — the update flow reads them as an ordering, so a lowered number tells '
+            + 'every member it is already up to date',
+      }));
+    }
+    return findings;
+  },
+};
+
+export default rule;
diff --git a/.claudinite/local/packs/canon-curation/pack-version-bumped.test.mjs b/.claudinite/local/packs/canon-curation/pack-version-bumped.test.mjs
new file mode 100644
index 00000000..7ecd3abe
--- /dev/null
+++ b/.claudinite/local/packs/canon-curation/pack-version-bumped.test.mjs
@@ -0,0 +1,106 @@
+import { test } from 'node:test';
+import assert from 'node:assert/strict';
+import { makeRepo, cleanup } from '../../../../engine-tests/helpers.mjs';
+import { buildContext } from '../../../../engine/checks/helpers/repo-context.mjs';
+import { runRule } from '../../../../engine/checks/helpers/work.mjs';
+import rule, { packsTouched, declaredPackVersion } from './pack-version-bumped.mjs';
+
+const manifest = (version) => `export default {\n  id: 'demo',\n  version: ${version},\n  minEngineVersion: 3,\n};\n`;
+
+// The work context a work rule receives — only the three members this rule reads.
+const work = (changedFiles, files = {}, base = {}) => ({
+  changedFiles,
+  read: (f) => files[f] ?? null,
+  readBase: (f) => base[f] ?? null,
+});
+
+const run = (...args) => rule.run(work(...args));
+
+// --- which changes are in scope ---------------------------------------------
+
+test('a pack directory is touched by any file under it, each pack once', () => {
+  assert.deepEqual(
+    packsTouched(['packs/demo/RULES.md', 'packs/demo/skills/x/SKILL.md', 'packs/other/pack.mjs']),
+    ['demo', 'other'],
+  );
+});
+
+test('the packs tree\'s own files are not a pack — they ship with the engine, not a directory copy', () => {
+  assert.deepEqual(packsTouched(['packs/README.md', 'packs/directory.GENERATED.md']), []);
+});
+
+test('the canon\'s own local packs are out of scope — they vendor nowhere and reach no member', () => {
+  assert.deepEqual(packsTouched(['.claudinite/local/packs/claudinite/RULES.md']), []);
+});
+
+// --- reading the declared version -------------------------------------------
+
+test('the manifest\'s own version is read, never minEngineVersion beside it', () => {
+  assert.equal(declaredPackVersion(manifest(2)), 2);
+  assert.equal(declaredPackVersion("export default { id: 'demo', minEngineVersion: 4 };\n"), null);
+});
+
+// --- the invariant ----------------------------------------------------------
+
+test('editing a pack without bumping its version fires, naming the next number', () => {
+  const findings = run(['packs/demo/RULES.md'], { 'packs/demo/pack.mjs': manifest(1) }, { 'packs/demo/pack.mjs': manifest(1) });
+  assert.equal(findings.length, 1);
+  assert.equal(findings[0].severity, 'blocking');
+  assert.equal(findings[0].file, 'packs/demo/pack.mjs');
+  assert.match(findings[0].what, /leaves its version at 1/);
+  assert.match(findings[0].fix, /to 2/);
+});
+
+test('a bump alongside the edit passes', () => {
+  assert.deepEqual(run(['packs/demo/RULES.md', 'packs/demo/pack.mjs'], { 'packs/demo/pack.mjs': manifest(2) }, { 'packs/demo/pack.mjs': manifest(1) }), []);
+});
+
+test('a version that moves backwards fires — every member would read it as "already current"', () => {
+  const findings = run(['packs/demo/pack.mjs'], { 'packs/demo/pack.mjs': manifest(1) }, { 'packs/demo/pack.mjs': manifest(3) });
+  assert.equal(findings.length, 1);
+  assert.match(findings[0].what, /backwards, 3 → 1/);
+});
+
+test('a pack this change introduces needs no bump — its first version ships to everyone', () => {
+  assert.deepEqual(run(['packs/demo/pack.mjs', 'packs/demo/RULES.md'], { 'packs/demo/pack.mjs': manifest(1) }, {}), []);
+});
+
+test('a pack this change deletes needs no bump — there is no manifest left to bump', () => {
+  assert.deepEqual(run(['packs/demo/pack.mjs', 'packs/demo/RULES.md'], {}, { 'packs/demo/pack.mjs': manifest(1) }), []);
+});
+
+test('each unbumped pack is reported separately — they are separate directory copies', () => {
+  const files = { 'packs/a/pack.mjs': manifest(1), 'packs/b/pack.mjs': manifest(5) };
+  const findings = run(['packs/a/RULES.md', 'packs/b/RULES.md'], files, files);
+  assert.deepEqual(findings.map((f) => f.file), ['packs/a/pack.mjs', 'packs/b/pack.mjs']);
+});
+
+test('a change touching no pack is silent', () => {
+  assert.deepEqual(run(['engine/version.mjs']), []);
+});
+
+// --- through the real work context ------------------------------------------
+// The stub above fixes what `read`/`readBase` answer; this proves the rule reads
+// the same pair off a real branch, base = the merge-base.
+
+test('end to end: an unbumped pack edit on a branch fires against the merge-base', () => {
+  const root = makeRepo({
+    base: { 'packs/demo/pack.mjs': manifest(1), 'packs/demo/RULES.md': '# Demo\n' },
+    changed: { 'packs/demo/RULES.md': '# Demo\n\nA new rule.\n' },
+  });
+  try {
+    const findings = runRule(rule, buildContext({ root, mode: 'changed' }));
+    assert.equal(findings.length, 1);
+    assert.match(findings[0].what, /leaves its version at 1/);
+  } finally { cleanup(root); }
+});
+
+test('end to end: the same edit with the bump is silent', () => {
+  const root = makeRepo({
+    base: { 'packs/demo/pack.mjs': manifest(1), 'packs/demo/RULES.md': '# Demo\n' },
+    changed: { 'packs/demo/pack.mjs': manifest(2), 'packs/demo/RULES.md': '# Demo\n\nA new rule.\n' },
+  });
+  try {
+    assert.deepEqual(runRule(rule, buildContext({ root, mode: 'changed' })), []);
+  } finally { cleanup(root); }
+});
